import{_ as o,o as t,c as a,ag as n}from"./chunks/framework.rAhUSuuf.js";const r="/assets/welcome-banner.Dpc7DMx2.jpeg",g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"welcome.md","filePath":"welcome.md","lastUpdated":1771327192000}'),i={name:"welcome.md"};function s(l,e,c,p,d,u){return t(),a("div",null,[...e[0]||(e[0]=[n('<img src="'+r+'" style="width:100%;border-radius:10px;margin-bottom:20px;" alt="Welcome Banner"><h3 id="welcome-to-skybase-innovations" tabindex="-1"><strong>Welcome to Skybase Innovations!</strong> <a class="header-anchor" href="#welcome-to-skybase-innovations" aria-label="Permalink to &quot;**Welcome to Skybase Innovations!**&quot;">​</a></h3><p>👋 We’re thrilled to have you on board! 🚀 Here, coding is our superpower, and innovation is our middle name! 💻 We can&#39;t wait to see the amazing things we&#39;ll achieve together. Let’s get ready to take the software development world by storm! ⚡️</p><h3 id="getting-started" tabindex="-1"><strong>Getting Started</strong> <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;**Getting Started**&quot;">​</a></h3><p>Here are some essential tips to help you start your journey with us:</p><ol><li><p><strong>Submit Your Citizenship Certificate</strong></p><p>To begin official work and payroll processing, please submit your citizenship certificate to the Admin team. 📄💼</p></li><li><p><strong>Official Company Email</strong></p><p>You will be given an official company email address (<a href="mailto:name@skybase.com.np" target="_blank" rel="noreferrer">name@skybase.com.np</a>). This email is essential for all work-related communications and documentation.</p></li><li><p><strong>Join Our Discord Server</strong></p><p>Our Discord server is the heart of our communication, providing updates and facilitating team collaboration. Here’s how to join:</p><ul><li><strong>Create a Discord Account with Company Email</strong>: If you don’t have one, sign up at Discord Sign-Up. (Make sure to keep your office and personal accounts separate.)</li><li><strong>Add HR</strong>: Add the HR representative to your Discord account.</li><li><strong>Receive Invitation</strong>: You will get an invitation link from HR to join the company server. Click on the link and follow the prompts to get started.</li><li><strong>Explore Channels</strong>: Familiarize yourself with various channels like #general and #team-discussion.</li></ul></li><li><p><strong>Learn to Use Karyabase</strong></p><p>Karya is our in-house project management and HR tool. It helps manage leave requests, track tasks, and monitor project progress.</p><ul><li><strong>Access Karyabase</strong>: You will receive your login credentials and the link via your official email or Discord message. Log in at <a href="https://karyabase.com" target="_blank" rel="noreferrer">karyabase.com</a> using the provided username and password.</li><li><strong>Key Features</strong>: Use the &quot;HR&quot; section for leave requests, attendance, and holiday management. See the <a href="/attendance.html">Attendance</a> policy for how to mark attendance (biometric vs Karyabase), late rules, and what happens if attendance is missing.</li><li><strong>Daily Updates</strong>: Post your daily work updates in the <strong>Updates</strong> section in Karyabase (not on Discord).</li></ul></li><li><p><strong>Set Up GitHub</strong></p><p>GitHub is crucial for version control and collaborative development.</p><ul><li><strong>Receive Credentials</strong>: Your GitHub account will be created by management, and you’ll receive login details via your company email.</li><li><strong>Access Repositories</strong>: You will get invitations to join relevant code repositories. Accept these to access the codebase.</li></ul></li><li><p><strong>Take Breaks and Enjoy Office Perks</strong></p><p>Don’t forget to take breaks! Our office kitchen has coffee, tea, and water available for you. ☕🍪</p></li><li><p><strong>Know Your Supervisor</strong></p><p>If you’re an intern, make sure to know your supervisor and don’t hesitate to ask for help. We’re here to support you! 👨‍🏫📚</p></li><li><p><strong>Explore</strong></p><p>Explore more on this handbook to know more about our office culture, policies and conventions📚</p></li><li><p><strong>Time Schedule</strong></p><p>Our regular office hours are <strong>10:00 AM to 6:00 PM</strong>. Your exact schedule may differ depending on your employment agreement.</p></li></ol><h3 id="contact-information" tabindex="-1"><strong>Contact Information</strong> <a class="header-anchor" href="#contact-information" aria-label="Permalink to &quot;**Contact Information**&quot;">​</a></h3><p>For any questions or assistance, feel free to reach out:</p><ul><li><strong>Operations</strong>: <code>info@skybase.com.np</code> | <code>+977-9845533797</code></li></ul><h3 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h3><p>We are excited to have you join our team at Skybase Innovations! Please ensure you complete the onboarding steps outlined above, and don’t hesitate to reach out if you need assistance. Let’s make some magic happen together! 🚀🌟</p>',11)])])}const h=o(i,[["render",s]]);export{g as __pageData,h as default};
